-- Phase 4 — Repair / Technical Jobs. No supplier returns.
BEGIN;
CREATE TABLE public.repair_jobs(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),repair_code text NOT NULL UNIQUE,laptop_id bigint NOT NULL REFERENCES laptops(id) ON DELETE RESTRICT,
 source_type text NOT NULL CHECK(source_type IN('QC','WARRANTY','TRADE_IN','INTERNAL')),source_id text,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','IN_PROGRESS','WAITING_PART','TESTING','COMPLETED','CANCELLED')),
 reported_issue text NOT NULL CHECK(length(btrim(reported_issue)) BETWEEN 1 AND 5000),diagnosis text NOT NULL DEFAULT '',repair_plan text NOT NULL DEFAULT '',resolution text NOT NULL DEFAULT '',priority text NOT NULL DEFAULT 'NORMAL' CHECK(priority IN('LOW','NORMAL','HIGH','URGENT')),
 assigned_to uuid REFERENCES user_profiles(id) ON DELETE RESTRICT,started_at timestamptz,completed_at timestamptz,labor_cost_vnd numeric NOT NULL DEFAULT 0 CHECK(labor_cost_vnd>=0),
 parts_cost_vnd numeric NOT NULL DEFAULT 0 CHECK(parts_cost_vnd>=0),total_cost_vnd numeric GENERATED ALWAYS AS(labor_cost_vnd+parts_cost_vnd) STORED,requires_re_qc boolean NOT NULL DEFAULT true,notes text NOT NULL DEFAULT '',
 idempotency_key text NOT NULL UNIQUE CHECK(length(btrim(idempotency_key)) BETWEEN 8 AND 100),completion_idempotency_key text UNIQUE CHECK(completion_idempotency_key IS NULL OR length(btrim(completion_idempotency_key)) BETWEEN 8 AND 100),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT timezone('utc',now()),updated_at timestamptz NOT NULL DEFAULT timezone('utc',now())
);
CREATE UNIQUE INDEX repair_jobs_one_active_per_laptop ON repair_jobs(laptop_id) WHERE status NOT IN('COMPLETED','CANCELLED');
CREATE INDEX repair_jobs_status_idx ON repair_jobs(status,priority,created_at DESC);
CREATE TABLE repair_parts(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,repair_job_id uuid NOT NULL REFERENCES repair_jobs(id) ON DELETE RESTRICT,part_type text NOT NULL CHECK(part_type IN('RAM','SSD','SCREEN','KEYBOARD','FAN','BATTERY','MAINBOARD','WIFI_CARD','CHARGER','HINGE','CABLE','THERMAL_MATERIAL','OTHER')),part_name text NOT NULL,serial text,quantity integer NOT NULL CHECK(quantity>0),unit_cost_vnd numeric NOT NULL CHECK(unit_cost_vnd>=0),total_cost_vnd numeric GENERATED ALWAYS AS(quantity*unit_cost_vnd) STORED,source text NOT NULL CHECK(source IN('STOCK','PURCHASED','CUSTOMER','SUPPLIER','OTHER')),notes text NOT NULL DEFAULT '',created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT timezone('utc',now()));
CREATE TABLE repair_actions(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,repair_job_id uuid NOT NULL REFERENCES repair_jobs(id) ON DELETE RESTRICT,action_type text NOT NULL CHECK(action_type IN('DIAGNOSIS','CLEANING','PART_REPLACEMENT','BIOS','SOFTWARE','THERMAL_SERVICE','TEST','OTHER')),description text NOT NULL,performed_by text NOT NULL,performed_at timestamptz NOT NULL DEFAULT timezone('utc',now()));
CREATE OR REPLACE FUNCTION next_repair_code() RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE p text:='REP-'||to_char(current_date,'YYYYMMDD')||'-';n int;BEGIN PERFORM pg_advisory_xact_lock(hashtext(p));SELECT coalesce(max(right(repair_code,3)::int),0)+1 INTO n FROM repair_jobs WHERE repair_code LIKE p||'%';RETURN p||lpad(n::text,3,'0');END $$;
CREATE OR REPLACE FUNCTION validate_repair_assignee(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF p_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM user_profiles WHERE id=p_id AND is_active AND role IN('ADMIN','TECH','TECHNICAL')) THEN RAISE EXCEPTION 'Kỹ thuật viên được giao không hợp lệ';END IF;END $$;
CREATE OR REPLACE FUNCTION start_repair_job(p_data jsonb,p_actor text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE l laptops%ROWTYPE;j repair_jobs%ROWTYPE;sid text:=nullif(p_data->>'source_id','');assignee uuid:=nullif(p_data->>'assigned_to','')::uuid;BEGIN SELECT * INTO j FROM repair_jobs WHERE idempotency_key=p_idempotency_key;IF FOUND THEN RETURN to_jsonb(j);END IF;PERFORM validate_repair_assignee(assignee);SELECT * INTO l FROM laptops WHERE id=(p_data->>'laptop_id')::bigint AND is_active FOR UPDATE;IF NOT FOUND OR l.status NOT IN('qc_failed','waiting_qc') THEN RAISE EXCEPTION 'Laptop không ở trạng thái được tạo phiếu sửa';END IF;IF p_data->>'source_type'='QC' AND (sid IS NULL OR NOT EXISTS(SELECT 1 FROM qc_inspections WHERE id::text=sid AND laptop_id=l.id AND result='FAIL')) THEN RAISE EXCEPTION 'QC nguồn không hợp lệ';END IF;INSERT INTO repair_jobs(repair_code,laptop_id,source_type,source_id,reported_issue,priority,assigned_to,requires_re_qc,created_by,idempotency_key) VALUES(next_repair_code(),l.id,p_data->>'source_type',sid,btrim(p_data->>'reported_issue'),coalesce(p_data->>'priority','NORMAL'),assignee,true,p_actor,p_idempotency_key) RETURNING * INTO j;PERFORM set_config('app.repair_transition','on',true);UPDATE laptops SET status='repair',is_locked=true,available_for_sale_at=NULL WHERE id=l.id;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('REPAIR_JOB',j.id::text,'CREATE',jsonb_build_object('repair_code',j.repair_code,'laptop_id',l.id,'source_type',j.source_type),p_actor);RETURN to_jsonb(j);END $$;
CREATE OR REPLACE FUNCTION update_repair_job(p_id uuid,p_data jsonb,p_actor text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE j repair_jobs%ROWTYPE;assignee uuid:=nullif(p_data->>'assigned_to','')::uuid;target text:=coalesce(p_data->>'status','');BEGIN SELECT * INTO j FROM repair_jobs WHERE id=p_id FOR UPDATE;IF NOT FOUND OR j.status IN('COMPLETED','CANCELLED') THEN RAISE EXCEPTION 'Phiếu sửa không còn được cập nhật';END IF;PERFORM validate_repair_assignee(assignee);IF target NOT IN('OPEN','IN_PROGRESS','WAITING_PART','TESTING') THEN RAISE EXCEPTION 'Trạng thái sửa chữa không hợp lệ';END IF;UPDATE repair_jobs SET status=target,diagnosis=left(coalesce(p_data->>'diagnosis',''),5000),repair_plan=left(coalesce(p_data->>'repair_plan',''),5000),priority=coalesce(p_data->>'priority',priority),assigned_to=assignee,labor_cost_vnd=coalesce((p_data->>'labor_cost_vnd')::numeric,labor_cost_vnd),notes=left(coalesce(p_data->>'notes',''),5000),started_at=CASE WHEN target<>'OPEN' THEN coalesce(started_at,timezone('utc',now())) ELSE started_at END WHERE id=p_id RETURNING * INTO j;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('REPAIR_JOB',j.id::text,'UPDATE',jsonb_build_object('status',j.status,'priority',j.priority,'assigned_to',j.assigned_to,'labor_cost_vnd',j.labor_cost_vnd),p_actor);RETURN to_jsonb(j);END $$;
CREATE OR REPLACE FUNCTION add_repair_part(p_job uuid,p_data jsonb,p_actor text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE p repair_parts%ROWTYPE;BEGIN IF NOT EXISTS(SELECT 1 FROM repair_jobs WHERE id=p_job AND status NOT IN('COMPLETED','CANCELLED') FOR UPDATE) THEN RAISE EXCEPTION 'Phiếu sửa không hoạt động';END IF;IF length(btrim(coalesce(p_data->>'part_name',''))) NOT BETWEEN 1 AND 240 THEN RAISE EXCEPTION 'Tên linh kiện không hợp lệ';END IF;INSERT INTO repair_parts(repair_job_id,part_type,part_name,serial,quantity,unit_cost_vnd,source,notes,created_by) VALUES(p_job,p_data->>'part_type',btrim(p_data->>'part_name'),nullif(left(btrim(coalesce(p_data->>'serial','')),100),''),(p_data->>'quantity')::int,(p_data->>'unit_cost_vnd')::numeric,p_data->>'source',left(coalesce(p_data->>'notes',''),3000),p_actor) RETURNING * INTO p;UPDATE repair_jobs SET parts_cost_vnd=(SELECT coalesce(sum(total_cost_vnd),0) FROM repair_parts WHERE repair_job_id=p_job) WHERE id=p_job;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('REPAIR_PART',p.id::text,'CREATE',jsonb_build_object('repair_job_id',p_job,'part_name',p.part_name,'quantity',p.quantity,'total_cost_vnd',p.total_cost_vnd),p_actor);RETURN to_jsonb(p);END $$;
CREATE OR REPLACE FUNCTION remove_repair_part(p_part_id bigint,p_actor text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE p repair_parts%ROWTYPE;BEGIN SELECT rp.* INTO p FROM repair_parts rp JOIN repair_jobs rj ON rj.id=rp.repair_job_id WHERE rp.id=p_part_id AND rj.status NOT IN('COMPLETED','CANCELLED') FOR UPDATE OF rp;IF NOT FOUND THEN RAISE EXCEPTION 'Linh kiện không tồn tại hoặc phiếu đã kết thúc';END IF;DELETE FROM repair_parts WHERE id=p.id;UPDATE repair_jobs SET parts_cost_vnd=(SELECT coalesce(sum(total_cost_vnd),0) FROM repair_parts WHERE repair_job_id=p.repair_job_id) WHERE id=p.repair_job_id;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('REPAIR_PART',p.id::text,'DELETE',jsonb_build_object('repair_job_id',p.repair_job_id,'part_name',p.part_name),p_actor);RETURN to_jsonb(p);END $$;
CREATE OR REPLACE FUNCTION add_repair_action(p_job uuid,p_data jsonb,p_actor text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE a repair_actions%ROWTYPE;BEGIN IF NOT EXISTS(SELECT 1 FROM repair_jobs WHERE id=p_job AND status NOT IN('COMPLETED','CANCELLED') FOR UPDATE) THEN RAISE EXCEPTION 'Phiếu sửa không hoạt động';END IF;IF length(btrim(coalesce(p_data->>'description',''))) NOT BETWEEN 1 AND 5000 THEN RAISE EXCEPTION 'Nội dung thao tác không hợp lệ';END IF;INSERT INTO repair_actions(repair_job_id,action_type,description,performed_by) VALUES(p_job,p_data->>'action_type',left(btrim(p_data->>'description'),5000),p_actor) RETURNING * INTO a;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('REPAIR_ACTION',a.id::text,'CREATE',jsonb_build_object('repair_job_id',p_job,'action_type',a.action_type),p_actor);RETURN to_jsonb(a);END $$;
CREATE OR REPLACE FUNCTION complete_repair_job(p_id uuid,p_resolution text,p_actor text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE j repair_jobs%ROWTYPE;BEGIN SELECT * INTO j FROM repair_jobs WHERE id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiếu sửa';END IF;IF j.status='COMPLETED' AND j.completion_idempotency_key=p_idempotency_key THEN RETURN to_jsonb(j);END IF;IF j.status IN('COMPLETED','CANCELLED') OR btrim(coalesce(p_resolution,''))='' OR length(btrim(coalesce(p_idempotency_key,''))) NOT BETWEEN 8 AND 100 THEN RAISE EXCEPTION 'Không thể hoàn tất phiếu sửa';END IF;UPDATE repair_jobs SET status='COMPLETED',resolution=left(p_resolution,5000),completed_at=timezone('utc',now()),completion_idempotency_key=p_idempotency_key,parts_cost_vnd=(SELECT coalesce(sum(total_cost_vnd),0) FROM repair_parts WHERE repair_job_id=p_id) WHERE id=p_id RETURNING * INTO j;PERFORM set_config('app.repair_transition','on',true);UPDATE laptops SET status='qc_failed',is_locked=true,available_for_sale_at=NULL WHERE id=j.laptop_id;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('REPAIR_JOB',j.id::text,'UPDATE',jsonb_build_object('status','COMPLETED','total_cost_vnd',j.total_cost_vnd,'requires_re_qc',true),p_actor);RETURN to_jsonb(j);END $$;
CREATE OR REPLACE FUNCTION cancel_repair_job(p_id uuid,p_reason text,p_actor text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE j repair_jobs%ROWTYPE;BEGIN SELECT * INTO j FROM repair_jobs WHERE id=p_id FOR UPDATE;IF NOT FOUND OR j.status IN('COMPLETED','CANCELLED') OR btrim(coalesce(p_reason,''))='' THEN RAISE EXCEPTION 'Không thể hủy phiếu sửa';END IF;UPDATE repair_jobs SET status='CANCELLED',resolution=left('Hủy: '||btrim(p_reason),5000),completed_at=timezone('utc',now()) WHERE id=p_id RETURNING * INTO j;PERFORM set_config('app.repair_transition','on',true);UPDATE laptops SET status='qc_failed',is_locked=true,available_for_sale_at=NULL WHERE id=j.laptop_id;INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('REPAIR_JOB',j.id::text,'UPDATE',jsonb_build_object('status','CANCELLED','reason',left(p_reason,1000)),p_actor);RETURN to_jsonb(j);END $$;

CREATE OR REPLACE FUNCTION guard_laptop_qc_transition() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status AND (OLD.status IN('waiting_qc','qc_in_progress','qc_failed') OR NEW.status IN('qc_in_progress','qc_failed')) AND current_setting('app.qc_transition',true) IS DISTINCT FROM 'on' AND current_setting('app.repair_transition',true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'Trạng thái QC chỉ được thay đổi qua quy trình kiểm tra kỹ thuật';END IF;RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION guard_repair_laptop_transition() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status AND (OLD.status='repair' OR NEW.status='repair') AND current_setting('app.repair_transition',true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'Trạng thái sửa chữa chỉ được đổi qua Repair workflow';END IF;RETURN NEW;END $$;CREATE TRIGGER guard_repair_laptop_transition_trigger BEFORE UPDATE OF status ON laptops FOR EACH ROW EXECUTE FUNCTION guard_repair_laptop_transition();
CREATE OR REPLACE FUNCTION guard_repair_history() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ DECLARE s text;BEGIN IF TG_TABLE_NAME='repair_jobs' THEN IF TG_OP='DELETE' OR OLD.status IN('COMPLETED','CANCELLED') THEN RAISE EXCEPTION 'Lịch sử sửa chữa đã kết thúc là bất biến';END IF;ELSE SELECT status INTO s FROM repair_jobs WHERE id=coalesce(NEW.repair_job_id,OLD.repair_job_id);IF TG_OP='DELETE' AND s IN('COMPLETED','CANCELLED') OR TG_OP='UPDATE' AND s IN('COMPLETED','CANCELLED') THEN RAISE EXCEPTION 'Chi tiết sửa chữa đã kết thúc là bất biến';END IF;END IF;RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END $$;CREATE TRIGGER repair_jobs_immutable BEFORE UPDATE OR DELETE ON repair_jobs FOR EACH ROW EXECUTE FUNCTION guard_repair_history();CREATE TRIGGER repair_parts_immutable BEFORE UPDATE OR DELETE ON repair_parts FOR EACH ROW EXECUTE FUNCTION guard_repair_history();CREATE TRIGGER repair_actions_immutable BEFORE UPDATE OR DELETE ON repair_actions FOR EACH ROW EXECUTE FUNCTION guard_repair_history();
CREATE TRIGGER repair_jobs_updated BEFORE UPDATE ON repair_jobs FOR EACH ROW EXECUTE FUNCTION set_updated_at();
ALTER TABLE repair_jobs ENABLE ROW LEVEL SECURITY;ALTER TABLE repair_parts ENABLE ROW LEVEL SECURITY;ALTER TABLE repair_actions ENABLE ROW LEVEL SECURITY;REVOKE ALL ON repair_jobs,repair_parts,repair_actions FROM PUBLIC,anon,authenticated;GRANT ALL ON repair_jobs,repair_parts,repair_actions TO service_role;GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;
REVOKE ALL ON FUNCTION next_repair_code(),validate_repair_assignee(uuid),start_repair_job(jsonb,text,text),update_repair_job(uuid,jsonb,text),add_repair_part(uuid,jsonb,text),remove_repair_part(bigint,text),add_repair_action(uuid,jsonb,text),complete_repair_job(uuid,text,text,text),cancel_repair_job(uuid,text,text),guard_repair_laptop_transition(),guard_repair_history() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION start_repair_job(jsonb,text,text),update_repair_job(uuid,jsonb,text),add_repair_part(uuid,jsonb,text),remove_repair_part(bigint,text),add_repair_action(uuid,jsonb,text),complete_repair_job(uuid,text,text,text),cancel_repair_job(uuid,text,text) TO service_role;
COMMIT;
